import{_ as o,o as d,c as t,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const _=JSON.parse('{"title":"Database architecture","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Database architecture | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/database"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Database architecture | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/database"}]]},"headers":[],"relativePath":"developer-guide/database.md","filePath":"developer-guide/database.md","lastUpdated":1788479753000}'),c={name:"developer-guide/database.md"};function s(n,e,i,r,l,p){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="database-architecture" tabindex="-1">Database architecture <a class="header-anchor" href="#database-architecture" aria-label="Permalink to &quot;Database architecture&quot;">​</a></h1><p>Single shared database. Catalog tables are <strong>central-only</strong> (no <code>tenant_id</code>). Workspace-scoped rows use <code>tenant_id</code> FKs.</p><h2 id="entity-overview" tabindex="-1">Entity overview <a class="header-anchor" href="#entity-overview" aria-label="Permalink to &quot;Entity overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>central_users          tenants ──has──► workspace_module_subscriptions ──► modules</span></span>\n<span class="line"><span>                              │                │</span></span>\n<span class="line"><span>                              │                └── workspace_module_subscription_history</span></span>\n<span class="line"><span>                              │</span></span>\n<span class="line"><span>                              ├── tenant_settings</span></span>\n<span class="line"><span>                              ├── billing profile columns (anchor, cycle, proration, next_billing_at)</span></span>\n<span class="line"><span>                              ├── invoices ──► invoice_items</span></span>\n<span class="line"><span>                              ├── payments ──► payment_transactions</span></span>\n<span class="line"><span>                              ├── payment_methods, billing_addresses</span></span>\n<span class="line"><span>                              ├── impersonation_sessions (central_user_id)</span></span>\n<span class="line"><span>                              ├── user_impersonation_sessions (actor_user_id, target_user_id)</span></span>\n<span class="line"><span>                              ├── (Cashier) subscriptions ──► subscription_items</span></span>\n<span class="line"><span>                              ├── stripe_id / pm_type / pm_last_four (Billable / Stripe)</span></span>\n<span class="line"><span>                              └── tenant_gateway_customers (provider-neutral customer_reference)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>modules ──► module_categories</span></span>\n<span class="line"><span>modules ──► module_dependencies (depends_on_module_id)</span></span>\n<span class="line"><span>payment_gateways ──► gateway_logs, webhook_logs, payment_attempts, tenant_gateway_customers</span></span>\n<span class="line"><span>system_settings (key/value — Central Application settings; see Settings section)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>lead_stages / lead_tags / lead_lead_tag / leads / lead_notes / lead_note_mentions / lead_follow_ups / lead_activities</span></span>\n<span class="line"><span>lead_assignment_histories</span></span>\n<span class="line"><span>  (tenant-scoped CRM — Leads module)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>companies / company_notes / company_activities</span></span>\n<span class="line"><span>contacts / contact_notes / contact_activities</span></span>\n<span class="line"><span>activities / activity_notes / activity_activities</span></span>\n<span class="line"><span>  (tenant-scoped CRM directory + engagements)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>opportunity_stages / opportunities / opportunity_tags / opportunity_opportunity_tag / opportunity_notes / opportunity_activities</span></span>\n<span class="line"><span>  (tenant-scoped sales deals + pipeline — Opportunities module)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>quotations / quotation_lines / quotation_notes / quotation_activities</span></span>\n<span class="line"><span>  (tenant-scoped quotes — Quotations module; hard-depends on Opportunities)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>contracts / contract_notes / contract_activities</span></span>\n<span class="line"><span>  (tenant-scoped agreements — Contracts module; hard-depends on Opportunities)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>resellers / reseller_notes / reseller_activities</span></span>\n<span class="line"><span>reseller_commission_entries</span></span>\n<span class="line"><span>  (tenant-scoped reseller partners + commission ledger — Resellers / Reseller Payouts; Resellers hard-depends on Payments; Reseller Payouts hard-depends on Resellers)</span></span>\n<span class="line"><span>customer_invoices.reseller_id (nullable FK → resellers)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>tasks / task_tags / task_task_tag / task_notes / task_note_mentions / task_activities</span></span>\n<span class="line"><span>task_digest_deliveries</span></span>\n<span class="line"><span>daily_summary_deliveries</span></span>\n<span class="line"><span>  (tenant-scoped work items — Tasks module + CRM daily digests; optional soft `project_id`)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>projects / project_members / project_notes / project_activities</span></span>\n<span class="line"><span>  (tenant-scoped Operations projects — Projects module; standalone free opt-in)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>automation_workflows / automation_triggers / automation_conditions / automation_actions</span></span>\n<span class="line"><span>automation_runs / automation_logs</span></span>\n<span class="line"><span>  (tenant-scoped Automation engine — billable Marketplace module `automation`)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>todos / todo_tags / todo_todo_tag</span></span>\n<span class="line"><span>  (tenant-scoped personal checklists — ToDos module; creator-scoped)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>announcements / announcement_reads</span></span>\n<span class="line"><span>  (tenant-scoped workspace announcements + read receipts — Announcements module; no view permission)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>knowledge_base_categories / knowledge_base_articles</span></span>\n<span class="line"><span>knowledge_base_article_notes / knowledge_base_article_activities</span></span>\n<span class="line"><span>  (tenant-scoped internal articles — Knowledge Base module; free Operations opt-in)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Analytics (`analytics`, display **Reports**) — **no dedicated tables**; executive overview + domain report aggregates over existing CRM / sales / billing / purchasing rows</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>chat_conversations / chat_conversation_members / chat_messages / chat_message_mentions</span></span>\n<span class="line"><span>chat_message_reactions / chat_message_pins / chat_message_attachments</span></span>\n<span class="line"><span>  (tenant-scoped Team Chat — channels/DMs, threads, reactions, pins, S3 attachments)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>communication_templates</span></span>\n<span class="line"><span>  (tenant-scoped plain-text templates — Communication Templates module)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>product_categories / products / product_notes / product_activities</span></span>\n<span class="line"><span>  (tenant-scoped product catalog — Products module)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>warehouses / warehouse_notes / warehouse_activities</span></span>\n<span class="line"><span>  (tenant-scoped stock locations — Warehouses module)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>stock_levels / stock_movements / stock_transfers ──► stock_transfer_lines</span></span>\n<span class="line"><span>  (tenant-scoped inventory ledger and transfers — Inventory module; hard-depends on Products)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>notifications</span></span>\n<span class="line"><span>  (Laravel database notifications — polymorphic notifiable)</span></span></code></pre></div><p><code>tenants</code> is the Cashier <strong>billable</strong> model. Cashier&#39;s <code>subscriptions</code>/<code>subscription_items</code> are the Stripe mirror. <strong><code>workspace_module_subscriptions</code> is the business source of truth</strong> for licensing. <strong><code>invoices</code> / <code>payments</code> are the financial ledger SoT.</strong></p><p>Plans, plan pivots, limit definitions, feature catalogs, and <code>tenant_subscriptions</code> have been <strong>removed</strong>.</p><h2 id="leads-module-tables" tabindex="-1">Leads module tables <a class="header-anchor" href="#leads-module-tables" aria-label="Permalink to &quot;Leads module tables&quot;">​</a></h2><h3 id="lead-stages" tabindex="-1"><code>lead_stages</code> <a class="header-anchor" href="#lead-stages" aria-label="Permalink to &quot;`lead_stages`&quot;">​</a></h3><p>Per-workspace pipeline: <code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>color</code>, <code>sort_order</code>, <code>is_won</code>, <code>is_lost</code>, <code>is_default</code>, soft deletes. Seeded New → Contacted → Qualified → Proposal → Negotiation → Won / Lost.</p><h3 id="lead-tags" tabindex="-1"><code>lead_tags</code> <a class="header-anchor" href="#lead-tags" aria-label="Permalink to &quot;`lead_tags`&quot;">​</a></h3><p>Workspace disposition catalog: <code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>color</code>, <code>sort_order</code>, <code>is_default</code>, <code>behavior</code> (<code>none</code>|<code>auto_follow_up</code>|<code>force_follow_up</code>), <code>auto_follow_up_days</code> (nullable). Independent of stages/status. Hard-deleted; pivot rows detach on delete.</p><h3 id="lead-lead-tag" tabindex="-1"><code>lead_lead_tag</code> <a class="header-anchor" href="#lead-lead-tag" aria-label="Permalink to &quot;`lead_lead_tag`&quot;">​</a></h3><p>Many-to-many: <code>lead_id</code>, <code>lead_tag_id</code> (unique pair).</p><h3 id="leads" tabindex="-1"><code>leads</code> <a class="header-anchor" href="#leads" aria-label="Permalink to &quot;`leads`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, contact fields, <code>stage_id</code>, <code>status</code> (<code>active</code>|<code>waiting</code>|<code>on_hold</code>|<code>closed</code>|<code>archived</code>), <code>priority</code> (<code>low</code>|<code>medium</code>|<code>high</code>|<code>urgent</code>), <code>assigned_to</code>, <code>lead_value</code> (renamed from <code>estimated_value</code>), <code>last_contacted_at</code>, <code>next_follow_up_at</code>, <code>converted_at</code>, <code>conversion_meta</code> (JSON), <code>contact_id</code> (nullable FK to <code>contacts</code>, set on convert when Contacts is installed), soft deletes. Status is <strong>independent</strong> of stage. Spatie activity log name <code>leads</code>.</p><h3 id="lead-notes-lead-note-mentions-lead-follow-ups-lead-activities" tabindex="-1"><code>lead_notes</code> / <code>lead_note_mentions</code> / <code>lead_follow_ups</code> / <code>lead_activities</code> <a class="header-anchor" href="#lead-notes-lead-note-mentions-lead-follow-ups-lead-activities" aria-label="Permalink to &quot;`lead_notes` / `lead_note_mentions` / `lead_follow_ups` / `lead_activities`&quot;">​</a></h3><p>Notes (author + body), mention rows (<code>lead_note_id</code>, <code>user_id</code>, <code>tenant_id</code> — unique per note+user), follow-ups (<code>due_at</code> / complete / status, nullable <code>lead_tag_id</code> for auto/force tag follow-ups), and CRM timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON). Mention tokens in note bodies use <code>@[Display Name](user:ID)</code>. Module <code>*_notes</code> tables (and <code>lead_assignment_histories</code>) carry <code>(tenant_id, parent_id, created_at)</code> indexes so show/timeline <strong>newest-first</strong> order stays index-friendly; domain <code>*_activities</code> already used the same pattern.</p><h3 id="lead-assignment-histories" tabindex="-1"><code>lead_assignment_histories</code> <a class="header-anchor" href="#lead-assignment-histories" aria-label="Permalink to &quot;`lead_assignment_histories`&quot;">​</a></h3><p><code>tenant_id</code>, <code>lead_id</code>, <code>old_user_id</code>, <code>new_user_id</code>, <code>changed_by</code>, <code>reason</code>, timestamps. Records assignee changes.</p><h2 id="contacts-module-tables" tabindex="-1">Contacts module tables <a class="header-anchor" href="#contacts-module-tables" aria-label="Permalink to &quot;Contacts module tables&quot;">​</a></h2><h3 id="contacts" tabindex="-1"><code>contacts</code> <a class="header-anchor" href="#contacts" aria-label="Permalink to &quot;`contacts`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>email</code>, <code>phone</code>, <code>company</code> (legacy free-text), <code>company_id</code> (nullable FK → <code>companies</code>, null on company delete), <code>job_title</code>, <code>source</code>, <code>source_meta</code> (JSON), <code>lifecycle_status</code> (<code>on_boarded</code>|<code>off_boarded</code>, default <code>on_boarded</code>), <code>assigned_to</code>, <code>created_by</code>, <code>last_contacted_at</code>, soft deletes. Spatie activity log name <code>contacts</code>. Directory record — no stage/status workflow. <strong>Lifecycle is independent of soft-delete (trash).</strong> When <code>company_id</code> is set, writes sync <code>company</code> from the linked Company name.</p><h3 id="contact-notes-contact-activities" tabindex="-1"><code>contact_notes</code> / <code>contact_activities</code> <a class="header-anchor" href="#contact-notes-contact-activities" aria-label="Permalink to &quot;`contact_notes` / `contact_activities`&quot;">​</a></h3><p>Notes (author + body) and CRM timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON).</p><h2 id="companies-module-tables" tabindex="-1">Companies module tables <a class="header-anchor" href="#companies-module-tables" aria-label="Permalink to &quot;Companies module tables&quot;">​</a></h2><h3 id="companies" tabindex="-1"><code>companies</code> <a class="header-anchor" href="#companies" aria-label="Permalink to &quot;`companies`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>email</code>, <code>phone</code>, <code>website</code>, <code>industry</code>, <code>address</code>, <code>source</code>, <code>source_meta</code> (JSON), <code>assigned_to</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>companies</code>. Directory record — no stage/status workflow.</p><h3 id="company-notes-company-activities" tabindex="-1"><code>company_notes</code> / <code>company_activities</code> <a class="header-anchor" href="#company-notes-company-activities" aria-label="Permalink to &quot;`company_notes` / `company_activities`&quot;">​</a></h3><p>Notes (author + body) and CRM timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON).</p><h2 id="activities-module-tables" tabindex="-1">Activities module tables <a class="header-anchor" href="#activities-module-tables" aria-label="Permalink to &quot;Activities module tables&quot;">​</a></h2><h3 id="activities" tabindex="-1"><code>activities</code> <a class="header-anchor" href="#activities" aria-label="Permalink to &quot;`activities`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>type</code> (<code>call</code>|<code>email</code>|<code>note</code>|<code>follow_up</code>|<code>other</code>), <code>subject</code>, <code>body</code>, <code>due_at</code>, <code>completed_at</code>, nullable <code>contact_id</code> / <code>company_id</code> / <code>lead_id</code>, <code>assigned_to</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>activities</code>. At least one related FK required on write.</p><h3 id="activity-notes-activity-activities" tabindex="-1"><code>activity_notes</code> / <code>activity_activities</code> <a class="header-anchor" href="#activity-notes-activity-activities" aria-label="Permalink to &quot;`activity_notes` / `activity_activities`&quot;">​</a></h3><p>Notes (author + body) and engagement timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes <code>completed</code>).</p><h2 id="opportunities-module-tables" tabindex="-1">Opportunities module tables <a class="header-anchor" href="#opportunities-module-tables" aria-label="Permalink to &quot;Opportunities module tables&quot;">​</a></h2><h3 id="opportunity-stages" tabindex="-1"><code>opportunity_stages</code> <a class="header-anchor" href="#opportunity-stages" aria-label="Permalink to &quot;`opportunity_stages`&quot;">​</a></h3><p>Per-workspace sales pipeline: <code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>color</code>, <code>sort_order</code>, <code>is_won</code>, <code>is_lost</code>, <code>is_default</code>, soft deletes. Seeded Prospecting → Qualification → Proposal → Negotiation → Won / Lost. Pipeline is <strong>inside</strong> Opportunities (not a separate module).</p><h3 id="opportunities" tabindex="-1"><code>opportunities</code> <a class="header-anchor" href="#opportunities" aria-label="Permalink to &quot;`opportunities`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>amount</code>, <code>currency</code> (default <code>USD</code>), <code>probability</code> (0–100), <code>expected_close_date</code>, <code>stage_id</code>, nullable <code>contact_id</code> / <code>company_id</code> / <code>lead_id</code>, <code>assigned_to</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>opportunities</code>. Related FKs are optional and soft-entitlement validated.</p><h3 id="opportunity-notes-opportunity-activities" tabindex="-1"><code>opportunity_notes</code> / <code>opportunity_activities</code> <a class="header-anchor" href="#opportunity-notes-opportunity-activities" aria-label="Permalink to &quot;`opportunity_notes` / `opportunity_activities`&quot;">​</a></h3><p>Notes (author + body) and deal timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes <code>stage_changed</code>).</p><h3 id="opportunity-tags-opportunity-opportunity-tag" tabindex="-1"><code>opportunity_tags</code> / <code>opportunity_opportunity_tag</code> <a class="header-anchor" href="#opportunity-tags-opportunity-opportunity-tag" aria-label="Permalink to &quot;`opportunity_tags` / `opportunity_opportunity_tag`&quot;">​</a></h3><p>Per-workspace opportunity tag catalog (<code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>color</code>, <code>sort_order</code>) and pivot (<code>opportunity_id</code>, <code>opportunity_tag_id</code>, unique pair). Create-only catalog API for MVP (no rename/delete/reorder routes). Assign via <code>tag_ids</code> on store/update or <code>PUT /opportunities/{id}/tags</code>. Filter list with <code>tag_id</code>.</p><h2 id="quotations-module-tables" tabindex="-1">Quotations module tables <a class="header-anchor" href="#quotations-module-tables" aria-label="Permalink to &quot;Quotations module tables&quot;">​</a></h2><h3 id="quotations" tabindex="-1"><code>quotations</code> <a class="header-anchor" href="#quotations" aria-label="Permalink to &quot;`quotations`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>opportunity_id</code> (required FK → <code>opportunities</code>, restrict on delete), nullable <code>contact_id</code> / <code>company_id</code>, <code>title</code>, <code>status</code> (<code>draft</code>|<code>sent</code>|<code>accepted</code>|<code>rejected</code>|<code>expired</code>), <code>currency</code>, <code>line_discount_type</code> (<code>none</code>|<code>percent</code>|<code>fixed</code>), <code>valid_until</code>, <code>subtotal</code> / <code>discount_total</code> / <code>tax_total</code> / <code>total</code>, <code>notes</code> (sanitized HTML memo), <code>terms_and_conditions</code> (sanitized HTML), <code>assigned_to</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>quotations</code>. Content edits are <strong>draft-only</strong>. Catalog version <strong>1.3.0</strong> (optional line <code>product_id</code>).</p><h3 id="quotation-lines" tabindex="-1"><code>quotation_lines</code> <a class="header-anchor" href="#quotation-lines" aria-label="Permalink to &quot;`quotation_lines`&quot;">​</a></h3><p><code>quotation_id</code>, nullable <code>product_id</code> (FK → <code>products</code>, <code>nullOnDelete</code>; optional via <code>LinkableProduct</code> when Products is entitled), required short <code>name</code>, optional long <code>body</code> (sanitized HTML), <code>quantity</code>, <code>unit_price</code>, <code>discount_value</code>, <code>tax_rate</code>, <code>line_total</code>, <code>sort_order</code>. Replaced in full on draft update; totals recalculated server-side from <code>line_discount_type</code> + per-line values. Server stores client-sent <code>name</code>/<code>body</code>/<code>unit_price</code> (does not re-copy from the product catalog on save).</p><h3 id="quotation-notes-quotation-activities" tabindex="-1"><code>quotation_notes</code> / <code>quotation_activities</code> <a class="header-anchor" href="#quotation-notes-quotation-activities" aria-label="Permalink to &quot;`quotation_notes` / `quotation_activities`&quot;">​</a></h3><p>Notes (author + body) and quote timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes <code>status_changed</code>).</p><h2 id="estimates-invoices-line-items-billing-documents" tabindex="-1">Estimates / Invoices line items (billing documents) <a class="header-anchor" href="#estimates-invoices-line-items-billing-documents" aria-label="Permalink to &quot;Estimates / Invoices line items (billing documents)&quot;">​</a></h2><p>Estimate and customer-invoice parents are documented in their module developer guides. Line tables mirror quotations:</p><h3 id="estimate-lines" tabindex="-1"><code>estimate_lines</code> <a class="header-anchor" href="#estimate-lines" aria-label="Permalink to &quot;`estimate_lines`&quot;">​</a></h3><p><code>estimate_id</code>, nullable <code>product_id</code> (FK → <code>products</code>, <code>nullOnDelete</code>; <code>LinkableProduct</code>), <code>name</code>, optional <code>body</code> (sanitized HTML), <code>quantity</code>, <code>unit_price</code>, <code>discount_value</code>, <code>tax_rate</code>, <code>line_total</code>, <code>sort_order</code>. Catalog <strong>estimates 1.3.0</strong>. Convert-to-invoice copies <code>product_id</code> with the line snapshot.</p><h3 id="customer-invoice-lines" tabindex="-1"><code>customer_invoice_lines</code> <a class="header-anchor" href="#customer-invoice-lines" aria-label="Permalink to &quot;`customer_invoice_lines`&quot;">​</a></h3><p><code>customer_invoice_id</code>, nullable <code>product_id</code> (FK → <code>products</code>, <code>nullOnDelete</code>; <code>LinkableProduct</code>), <code>name</code>, optional <code>body</code> (sanitized HTML), <code>quantity</code>, <code>unit_price</code>, <code>discount_value</code>, <code>tax_rate</code>, <code>line_total</code>, <code>sort_order</code>. Catalog <strong>invoices 1.5.0</strong>. Recurring occurrence clone copies <code>product_id</code>.</p><h2 id="contracts-module-tables" tabindex="-1">Contracts module tables <a class="header-anchor" href="#contracts-module-tables" aria-label="Permalink to &quot;Contracts module tables&quot;">​</a></h2><h3 id="contracts" tabindex="-1"><code>contracts</code> <a class="header-anchor" href="#contracts" aria-label="Permalink to &quot;`contracts`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>opportunity_id</code> (required FK → <code>opportunities</code>, restrict on delete), nullable <code>quotation_id</code> (null on quotation hard delete; soft-optional via <code>LinkableQuotation</code> — same opportunity, Quotations entitled, not soft-deleted), <code>title</code>, <code>status</code> (<code>draft</code>|<code>active</code>|<code>expired</code>|<code>terminated</code>), <code>party_name</code>, <code>start_date</code>, <code>end_date</code>, <code>value</code>, <code>currency</code>, <code>notes</code> (HTML memo, sanitized), <code>description</code> (HTML memo, sanitized), <code>assigned_to</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>contracts</code>. Content edits are <strong>draft-only</strong>; status/assign remain available after activate.</p><h3 id="contract-notes-contract-activities" tabindex="-1"><code>contract_notes</code> / <code>contract_activities</code> <a class="header-anchor" href="#contract-notes-contract-activities" aria-label="Permalink to &quot;`contract_notes` / `contract_activities`&quot;">​</a></h3><p>Notes (author + body) and agreement timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes <code>status_changed</code>).</p><h2 id="resellers-reseller-payouts-module-tables" tabindex="-1">Resellers / Reseller Payouts module tables <a class="header-anchor" href="#resellers-reseller-payouts-module-tables" aria-label="Permalink to &quot;Resellers / Reseller Payouts module tables&quot;">​</a></h2><h3 id="resellers" tabindex="-1"><code>resellers</code> <a class="header-anchor" href="#resellers" aria-label="Permalink to &quot;`resellers`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, nullable <code>email</code> / <code>phone</code> / <code>company_name</code> / <code>notes</code> (profile scalar), <code>status</code> (<code>active</code>|<code>inactive</code>), <code>commission_rate</code> / <code>owner_commission_rate</code> (decimal 5,2, default 0), <code>assigned_to</code>, <code>created_by</code>, nullable <code>user_id</code> (linked same-workspace login; unique per tenant when set), soft deletes. Spatie activity log name <code>resellers</code>. Indexes on tenant+name/email/assigned_to/status.</p><h3 id="reseller-notes" tabindex="-1"><code>reseller_notes</code> <a class="header-anchor" href="#reseller-notes" aria-label="Permalink to &quot;`reseller_notes`&quot;">​</a></h3><p>Threaded notes (API key <code>note_entries</code>). <code>tenant_id</code>, <code>reseller_id</code> (cascade), <code>body</code> (text), <code>created_by</code>, timestamps. Index on <code>(reseller_id, created_at)</code>.</p><h3 id="reseller-activities" tabindex="-1"><code>reseller_activities</code> <a class="header-anchor" href="#reseller-activities" aria-label="Permalink to &quot;`reseller_activities`&quot;">​</a></h3><p>Domain timeline. <code>tenant_id</code>, <code>reseller_id</code> (cascade), <code>type</code> (string; see <code>ResellerActivityTypeEnum</code>), <code>description</code>, nullable <code>properties</code> (json), nullable <code>actor_id</code>, timestamps. Index on <code>(reseller_id, created_at)</code>.</p><h3 id="reseller-commission-entries" tabindex="-1"><code>reseller_commission_entries</code> <a class="header-anchor" href="#reseller-commission-entries" aria-label="Permalink to &quot;`reseller_commission_entries`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>reseller_id</code> (cascade), <code>customer_invoice_id</code> (cascade), <code>party</code> (<code>reseller</code>|<code>owner</code>), nullable <code>party_user_id</code>, <code>invoice_total</code> / <code>rate</code> / <code>amount</code>, <code>currency</code> (3-char, default <code>USD</code>), <code>status</code> (<code>accrued</code>|<code>approved</code>|<code>paid</code>|<code>void</code>), approve/pay/void timestamps + actor FKs. Unique <code>(customer_invoice_id, party)</code>. Spatie activity log name <code>reseller_commission_entries</code>. Accrues only when invoice status becomes fully <strong>Paid</strong> and <code>reseller-payouts</code> is entitled.</p><h3 id="customer-invoices-contract-id" tabindex="-1"><code>customer_invoices.contract_id</code> <a class="header-anchor" href="#customer-invoices-contract-id" aria-label="Permalink to &quot;`customer_invoices.contract_id`&quot;">​</a></h3><p>Nullable FK → <code>contracts</code> (<code>nullOnDelete</code>), indexed with <code>tenant_id</code>. Set by <code>POST /contracts/{id}/convert</code>. Repeatable — no unique index. Catalog <strong>invoices 1.6.0</strong>.</p><h3 id="customer-invoices-reseller-id" tabindex="-1"><code>customer_invoices.reseller_id</code> <a class="header-anchor" href="#customer-invoices-reseller-id" aria-label="Permalink to &quot;`customer_invoices.reseller_id`&quot;">​</a></h3><p>Nullable FK → <code>resellers</code> (<code>nullOnDelete</code>), indexed with <code>tenant_id</code>. Optional link validated via <code>LinkableReseller</code> when Resellers is entitled. (Customer invoice module tables are documented in the Invoices developer guide; this column is the Phase 1 Resellers extension.) Recurrence columns on the same table (1.1.0): <code>is_recurring</code>, <code>recurrence_frequency</code>, <code>recurrence_status</code>, <code>recurrence_next_issue_on</code>, <code>recurrence_ends_on</code>, <code>recurrence_due_days</code>, <code>recurring_source_invoice_id</code> (self-FK, null on delete).</p><h2 id="todos-module-tables" tabindex="-1">ToDos module tables <a class="header-anchor" href="#todos-module-tables" aria-label="Permalink to &quot;ToDos module tables&quot;">​</a></h2><h3 id="todos" tabindex="-1"><code>todos</code> <a class="header-anchor" href="#todos" aria-label="Permalink to &quot;`todos`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>title</code>, <code>description</code>, <code>status</code> (<code>open</code>|<code>in_progress</code>|<code>completed</code>|<code>cancelled</code>), <code>priority</code> (<code>low</code>|<code>medium</code>|<code>high</code>|<code>urgent</code>), <code>due_at</code>, <code>created_by</code>, <code>completed_at</code>, soft deletes. Spatie activity log name <code>todos</code>. UI labels <code>open</code> as <strong>To Do</strong>. Visibility is creator-scoped; workspace owner (<code>superadmin</code>) can view all. Only the creator may update or delete.</p><h3 id="todo-tags-todo-todo-tag" tabindex="-1"><code>todo_tags</code> / <code>todo_todo_tag</code> <a class="header-anchor" href="#todo-tags-todo-todo-tag" aria-label="Permalink to &quot;`todo_tags` / `todo_todo_tag`&quot;">​</a></h3><p>Per-workspace to-do tag catalog (<code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>color</code>, <code>sort_order</code>) and pivot (<code>todo_id</code>, <code>todo_tag_id</code>, unique pair). Create-only catalog API for MVP. Assign via <code>tag_ids</code> or <code>PUT /todos/{id}/tags</code>. Filter with <code>tag_id</code>.</p><h3 id="announcements" tabindex="-1"><code>announcements</code> <a class="header-anchor" href="#announcements" aria-label="Permalink to &quot;`announcements`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>title</code>, <code>body</code>, <code>status</code> (<code>draft</code>|<code>published</code>|<code>archived</code>), <code>published_at</code>, <code>expires_at</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>announcements</code>. Audience visibility is module-gated only (no <code>announcements.view</code> permission); mutations use create/update/delete/restore/force.delete.</p><h3 id="announcement-reads" tabindex="-1"><code>announcement_reads</code> <a class="header-anchor" href="#announcement-reads" aria-label="Permalink to &quot;`announcement_reads`&quot;">​</a></h3><p><code>tenant_id</code>, <code>announcement_id</code>, <code>user_id</code>, <code>first_read_at</code>, <code>last_read_at</code>, <code>first_read_ip</code>, <code>last_read_ip</code>, unique <code>(announcement_id, user_id)</code>. Records first and last read times/IPs when users mark announcements as read.</p><h2 id="knowledge-base-module-tables" tabindex="-1">Knowledge Base module tables <a class="header-anchor" href="#knowledge-base-module-tables" aria-label="Permalink to &quot;Knowledge Base module tables&quot;">​</a></h2><h3 id="knowledge-base-categories" tabindex="-1"><code>knowledge_base_categories</code> <a class="header-anchor" href="#knowledge-base-categories" aria-label="Permalink to &quot;`knowledge_base_categories`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>sort_order</code> (default 0), <code>is_active</code> (default true), soft deletes. Unique <code>(tenant_id, slug)</code>, index <code>(tenant_id, sort_order)</code>. Flat categories only. Soft/force delete is blocked in the service while articles still reference the category (force also considers trashed articles).</p><h3 id="knowledge-base-articles" tabindex="-1"><code>knowledge_base_articles</code> <a class="header-anchor" href="#knowledge-base-articles" aria-label="Permalink to &quot;`knowledge_base_articles`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, nullable <code>category_id</code> (FK → <code>knowledge_base_categories</code>, null on delete), <code>title</code>, <code>slug</code>, nullable <code>excerpt</code>, <code>body</code> (TipTap HTML), <code>status</code> (<code>draft</code>|<code>published</code>|<code>archived</code>), nullable <code>published_at</code> (<code>UtcDateTime</code>), nullable <code>created_by</code>, soft deletes. Unique <code>(tenant_id, slug)</code>, indexes <code>(tenant_id, status)</code> and <code>(tenant_id, title)</code>. Spatie activity log name <code>knowledge-base</code>. Audience list scope is published-only unless the actor has <code>knowledge-base.update</code>.</p><h3 id="knowledge-base-article-notes-knowledge-base-article-activities" tabindex="-1"><code>knowledge_base_article_notes</code> / <code>knowledge_base_article_activities</code> <a class="header-anchor" href="#knowledge-base-article-notes-knowledge-base-article-activities" aria-label="Permalink to &quot;`knowledge_base_article_notes` / `knowledge_base_article_activities`&quot;">​</a></h3><p>Notes (<code>knowledge_base_article_id</code>, <code>user_id</code>, <code>body</code>) and article domain timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes status changes).</p><h2 id="team-chat-module-tables" tabindex="-1">Team Chat module tables <a class="header-anchor" href="#team-chat-module-tables" aria-label="Permalink to &quot;Team Chat module tables&quot;">​</a></h2><h3 id="chat-conversations" tabindex="-1"><code>chat_conversations</code> <a class="header-anchor" href="#chat-conversations" aria-label="Permalink to &quot;`chat_conversations`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>type</code> (<code>channel</code>|<code>dm</code>|<code>group_dm</code>), <code>visibility</code> (<code>public</code>|<code>private</code>, channels), <code>name</code>, <code>slug</code>, <code>description</code>, <code>dm_key</code> (sorted pair for 1:1 DMs), <code>created_by</code>, <code>is_archived</code>, <code>last_message_at</code>, soft deletes. Unique <code>(tenant_id, slug)</code> and <code>(tenant_id, dm_key)</code>. Archiving clears <code>slug</code> so names can be reused.</p><h3 id="chat-conversation-members" tabindex="-1"><code>chat_conversation_members</code> <a class="header-anchor" href="#chat-conversation-members" aria-label="Permalink to &quot;`chat_conversation_members`&quot;">​</a></h3><p><code>tenant_id</code>, <code>conversation_id</code>, <code>user_id</code>, <code>role</code> (<code>owner</code>|<code>moderator</code>|<code>member</code>), <code>joined_at</code>, <code>last_read_at</code>, <code>muted_until</code>. Unique <code>(conversation_id, user_id)</code>.</p><h3 id="chat-messages" tabindex="-1"><code>chat_messages</code> <a class="header-anchor" href="#chat-messages" aria-label="Permalink to &quot;`chat_messages`&quot;">​</a></h3><p><code>tenant_id</code>, <code>conversation_id</code>, <code>user_id</code> (author), <code>parent_id</code> (thread root, same conversation), <code>body</code>, <code>edited_at</code>, soft deletes. Mentions use <code>@[Display Name](user:ID)</code>.</p><h3 id="chat-message-mentions-chat-message-reactions-chat-message-pins" tabindex="-1"><code>chat_message_mentions</code> / <code>chat_message_reactions</code> / <code>chat_message_pins</code> <a class="header-anchor" href="#chat-message-mentions-chat-message-reactions-chat-message-pins" aria-label="Permalink to &quot;`chat_message_mentions` / `chat_message_reactions` / `chat_message_pins`&quot;">​</a></h3><p>Mention rows (<code>message_id</code>, <code>user_id</code>, unique per pair). Reactions (<code>message_id</code>, <code>user_id</code>, <code>emoji</code>). Pins (<code>conversation_id</code>, <code>message_id</code>, <code>pinned_by</code>).</p><h3 id="chat-message-attachments" tabindex="-1"><code>chat_message_attachments</code> <a class="header-anchor" href="#chat-message-attachments" aria-label="Permalink to &quot;`chat_message_attachments`&quot;">​</a></h3><p><code>tenant_id</code>, <code>message_id</code>, <code>disk</code>, <code>path</code>, <code>original_name</code>, <code>mime</code>, <code>size_bytes</code>. Files live on the uploads disk under the tenant prefix. Soft-deleting a message removes storage objects immediately; <code>team-chat:purge-expired</code> also deletes aged messages and files when retention days &gt; 0.</p><h2 id="tasks-module-tables" tabindex="-1">Tasks module tables <a class="header-anchor" href="#tasks-module-tables" aria-label="Permalink to &quot;Tasks module tables&quot;">​</a></h2><h3 id="tasks" tabindex="-1"><code>tasks</code> <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;`tasks`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>title</code>, <code>description</code>, <code>status</code> (<code>open</code>|<code>in_progress</code>|<code>waiting</code>|<code>completed</code>|<code>cancelled</code>), <code>priority</code> (<code>low</code>|<code>medium</code>|<code>high</code>|<code>urgent</code>), <code>due_at</code>, <code>assigned_to</code>, <code>created_by</code>, nullable <code>project_id</code> (FK → <code>projects</code>, null on delete; soft entitlement via <code>LinkableProject</code> — Projects must be entitled and the project visible to the actor), <code>completed_at</code>, soft deletes. Spatie activity log name <code>tasks</code>. UI labels <code>open</code> as <strong>To Do</strong>. Catalog version <strong>1.2.0</strong> (added <code>project_id</code>).</p><h3 id="projects" tabindex="-1"><code>projects</code> <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;`projects`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>title</code> (not <code>name</code>), <code>status</code> (<code>planned</code>|<code>active</code>|<code>on_hold</code>|<code>completed</code>|<code>cancelled</code>, default <code>planned</code>), nullable <code>description</code>, nullable soft FKs <code>contact_id</code> / <code>company_id</code> / <code>opportunity_id</code> (null on delete), nullable date <code>starts_on</code> / <code>ends_on</code>, <code>assigned_to</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>projects</code>. Indexes on tenant+status/assignee/contact/company/opportunity/ends_on/title.</p><h3 id="project-members" tabindex="-1"><code>project_members</code> <a class="header-anchor" href="#project-members" aria-label="Permalink to &quot;`project_members`&quot;">​</a></h3><p>Pivot: <code>tenant_id</code>, <code>project_id</code> (cascade), <code>user_id</code>, timestamps. Unique <code>(project_id, user_id)</code>. Assignee is not duplicated as a member.</p><h3 id="project-notes-project-activities" tabindex="-1"><code>project_notes</code> / <code>project_activities</code> <a class="header-anchor" href="#project-notes-project-activities" aria-label="Permalink to &quot;`project_notes` / `project_activities`&quot;">​</a></h3><p>Notes (author + body) and project timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes <code>members_synced</code>, <code>status_changed</code>).</p><h3 id="task-tags-task-task-tag" tabindex="-1"><code>task_tags</code> / <code>task_task_tag</code> <a class="header-anchor" href="#task-tags-task-task-tag" aria-label="Permalink to &quot;`task_tags` / `task_task_tag`&quot;">​</a></h3><p>Per-workspace task tag catalog (<code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>color</code>, <code>sort_order</code>) and pivot (<code>task_id</code>, <code>task_tag_id</code>, unique pair). Create-only catalog API for MVP. Assign via <code>tag_ids</code> or <code>PUT /tasks/{id}/tags</code>. Filter with <code>tag_id</code>.</p><h3 id="task-notes-task-note-mentions-task-activities" tabindex="-1"><code>task_notes</code> / <code>task_note_mentions</code> / <code>task_activities</code> <a class="header-anchor" href="#task-notes-task-note-mentions-task-activities" aria-label="Permalink to &quot;`task_notes` / `task_note_mentions` / `task_activities`&quot;">​</a></h3><p>Notes / comments (author + body), mention rows (<code>task_note_id</code>, <code>user_id</code>, <code>tenant_id</code> — unique per note+user), and task timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON). Mention tokens use the same <code>@[Display Name](user:ID)</code> syntax as lead notes.</p><h3 id="task-digest-deliveries" tabindex="-1"><code>task_digest_deliveries</code> <a class="header-anchor" href="#task-digest-deliveries" aria-label="Permalink to &quot;`task_digest_deliveries`&quot;">​</a></h3><p>Once-per-day mail ledger for task due digests: <code>tenant_id</code>, <code>user_id</code>, <code>digest_date</code>, <code>status</code> (<code>queued</code>|<code>sent</code>|<code>failed</code>), <code>attempts</code>, <code>queued_at</code> / <code>sent_at</code> / <code>failed_at</code> / <code>retry_after</code>, <code>failure_reason</code>. Unique <code>(tenant_id, user_id, digest_date)</code>.</p><h3 id="daily-summary-deliveries" tabindex="-1"><code>daily_summary_deliveries</code> <a class="header-anchor" href="#daily-summary-deliveries" aria-label="Permalink to &quot;`daily_summary_deliveries`&quot;">​</a></h3><p>Once-per-day mail ledger for CRM summaries: same columns as task digests plus <code>kind</code> (<code>personal</code>|<code>team</code>|<code>department_weekly</code>). Unique <code>(tenant_id, user_id, digest_date, kind)</code>. Stale <code>queued</code> may be reclaimed after 45 minutes (max 5 attempts).</p><h2 id="automation-module-tables" tabindex="-1">Automation module tables <a class="header-anchor" href="#automation-module-tables" aria-label="Permalink to &quot;Automation module tables&quot;">​</a></h2><h3 id="automation-workflows" tabindex="-1"><code>automation_workflows</code> <a class="header-anchor" href="#automation-workflows" aria-label="Permalink to &quot;`automation_workflows`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, <code>description</code>, <code>is_active</code>, <code>version</code>, <code>template_key</code>, <code>metadata</code> JSON, <code>created_by</code>, <code>updated_by</code>, timestamps. Spatie activity log name <code>automation</code>. Always created inactive; activation is a separate gate (wired trigger + required modules entitled).</p><h3 id="automation-triggers-automation-conditions-automation-actions" tabindex="-1"><code>automation_triggers</code> / <code>automation_conditions</code> / <code>automation_actions</code> <a class="header-anchor" href="#automation-triggers-automation-conditions-automation-actions" aria-label="Permalink to &quot;`automation_triggers` / `automation_conditions` / `automation_actions`&quot;">​</a></h3><p>Per-workflow trigger (<code>type</code>, <code>config</code> JSON), conditions (<code>field</code>, <code>operator</code>, <code>value</code> JSON, <code>logic_group</code>, <code>sort_order</code>), and ordered actions (<code>type</code>, <code>config</code> JSON, <code>delay_seconds</code>, <code>sort_order</code>).</p><h3 id="automation-runs-automation-logs" tabindex="-1"><code>automation_runs</code> / <code>automation_logs</code> <a class="header-anchor" href="#automation-runs-automation-logs" aria-label="Permalink to &quot;`automation_runs` / `automation_logs`&quot;">​</a></h3><p>Runs: <code>workflow_id</code>, <code>uuid</code>, <code>status</code> (<code>pending</code>|<code>running</code>|<code>completed</code>|<code>failed</code>|<code>skipped</code>|<code>cancelled</code>), <code>trigger_type</code>, <code>trigger_payload</code> JSON, <code>error_message</code>, <code>started_at</code>, <code>finished_at</code>. Logs: <code>run_id</code>, <code>level</code>, <code>step</code>, <code>message</code>, <code>context</code> JSON. Exhausted queue retries mark the run <code>failed</code> via <code>ExecuteAutomationRunJob::failed()</code>.</p><h3 id="users-crm-flags" tabindex="-1">Users CRM flags <a class="header-anchor" href="#users-crm-flags" aria-label="Permalink to &quot;Users CRM flags&quot;">​</a></h3><p>Tenant <code>users</code> includes:</p><ul><li><code>exclude_from_lead_auto_assign</code> (boolean) — omit from lead assignee pickers / equal distribute</li><li><code>receive_website_leads</code> (boolean) — opt-in for custom webhook website recipient pool</li><li><code>lead_commission_rate</code> (nullable decimal 0–100) — default rate snapshotted onto leads on assign</li><li><code>receive_all_users_daily_summary</code> (boolean, default <code>false</code>) — receive team CRM summary email instead of personal</li></ul><h2 id="vendors-module-tables" tabindex="-1">Vendors module tables <a class="header-anchor" href="#vendors-module-tables" aria-label="Permalink to &quot;Vendors module tables&quot;">​</a></h2><h3 id="vendors" tabindex="-1"><code>vendors</code> <a class="header-anchor" href="#vendors" aria-label="Permalink to &quot;`vendors`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, nullable <code>email</code> / <code>phone</code> / <code>website</code> / <code>address</code> / <code>tax_id</code> / <code>payment_terms</code>, <code>currency</code> (nullable, 3-char), <code>status</code> (<code>active</code>|<code>inactive</code>), <code>assigned_to</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>vendors</code>. Unique <code>uuid</code>. Indexes on tenant+name/email/assigned_to/status.</p><h3 id="vendor-notes-vendor-activities" tabindex="-1"><code>vendor_notes</code> / <code>vendor_activities</code> <a class="header-anchor" href="#vendor-notes-vendor-activities" aria-label="Permalink to &quot;`vendor_notes` / `vendor_activities`&quot;">​</a></h3><p>Notes (author + body) and supplier timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON).</p><h2 id="purchase-orders-module-tables" tabindex="-1">Purchase Orders module tables <a class="header-anchor" href="#purchase-orders-module-tables" aria-label="Permalink to &quot;Purchase Orders module tables&quot;">​</a></h2><h3 id="purchase-orders" tabindex="-1"><code>purchase_orders</code> <a class="header-anchor" href="#purchase-orders" aria-label="Permalink to &quot;`purchase_orders`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>number</code> (unique per tenant), required <code>vendor_id</code> (FK → <code>vendors</code>, restrict on delete), <code>title</code>, <code>notes</code>, <code>status</code> (<code>draft</code>|<code>sent</code>|<code>partially_received</code>|<code>received</code>|<code>cancelled</code>), <code>currency</code>, <code>subtotal</code> / <code>tax_total</code> / <code>total</code>, <code>order_date</code>, <code>expected_date</code>, <code>assigned_to</code>, <code>created_by</code>, soft deletes. Spatie activity log name <code>purchase-orders</code>. Content edits are <strong>draft-only</strong>; send/receive/cancel/assign remain available per status machine. Receiving is acknowledgement-only (no inventory posting).</p><h3 id="purchase-order-lines" tabindex="-1"><code>purchase_order_lines</code> <a class="header-anchor" href="#purchase-order-lines" aria-label="Permalink to &quot;`purchase_order_lines`&quot;">​</a></h3><p><code>tenant_id</code>, <code>purchase_order_id</code> (cascade), nullable <code>product_id</code> (FK → <code>products</code>, null on product delete), <code>description</code>, <code>quantity</code>, <code>unit_price</code>, <code>tax_rate</code>, <code>line_total</code>, <code>sort_order</code>. Synced replace-all on create/update via <code>PurchaseOrderService::syncLines()</code>. Product link is optional and supports stock receipt when Products and Inventory are entitled.</p><h3 id="purchase-order-notes-purchase-order-activities" tabindex="-1"><code>purchase_order_notes</code> / <code>purchase_order_activities</code> <a class="header-anchor" href="#purchase-order-notes-purchase-order-activities" aria-label="Permalink to &quot;`purchase_order_notes` / `purchase_order_activities`&quot;">​</a></h3><p>Notes (author + body) and procurement timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes <code>status_changed</code>, <code>converted</code>).</p><h2 id="expenses-module-tables" tabindex="-1">Expenses module tables <a class="header-anchor" href="#expenses-module-tables" aria-label="Permalink to &quot;Expenses module tables&quot;">​</a></h2><h3 id="expense-categories" tabindex="-1"><code>expense_categories</code> <a class="header-anchor" href="#expense-categories" aria-label="Permalink to &quot;`expense_categories`&quot;">​</a></h3><p><code>tenant_id</code>, unique <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>sort_order</code> (default 0), <code>is_active</code> (default true), timestamps, soft deletes. Unique <code>(tenant_id, slug)</code>, index <code>(tenant_id, sort_order)</code>. Tenant-managed lookup; starter slugs <code>travel|office|software|utilities|other</code> are lazy-seeded and stay immutable on rename. <strong>Other</strong> cannot be deleted. Spatie activity log name <code>expense-categories</code>. Delete is also blocked in the service while expenses exist.</p><h3 id="expenses" tabindex="-1"><code>expenses</code> <a class="header-anchor" href="#expenses" aria-label="Permalink to &quot;`expenses`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>number</code> (unique per tenant), <code>title</code>, nullable <code>category_id</code> (FK → <code>expense_categories</code>, null on delete), <code>amount</code>, <code>tax_amount</code>, <code>currency</code>, <code>expense_date</code>, <code>status</code> (<code>draft</code>|<code>submitted</code>|<code>approved</code>|<code>rejected</code>|<code>paid</code>|<code>cancelled</code>), nullable <code>vendor_id</code> (FK → <code>vendors</code>, null on delete; soft entitlement), nullable unique <code>purchase_order_id</code> (FK → <code>purchase_orders</code>, null on delete; soft entitlement; one expense per PO), <code>assigned_to</code>, <code>created_by</code>, <code>notes</code>, soft deletes. Spatie activity log name <code>expenses</code>. No line-item child table in MVP. Content edits are <strong>draft-only</strong>.</p><h3 id="expense-notes-expense-activities" tabindex="-1"><code>expense_notes</code> / <code>expense_activities</code> <a class="header-anchor" href="#expense-notes-expense-activities" aria-label="Permalink to &quot;`expense_notes` / `expense_activities`&quot;">​</a></h3><p>Notes (author + body) and expense timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes <code>status_changed</code>).</p><h2 id="help-desk-module-tables" tabindex="-1">Help Desk module tables <a class="header-anchor" href="#help-desk-module-tables" aria-label="Permalink to &quot;Help Desk module tables&quot;">​</a></h2><h3 id="help-desk-categories" tabindex="-1"><code>help_desk_categories</code> <a class="header-anchor" href="#help-desk-categories" aria-label="Permalink to &quot;`help_desk_categories`&quot;">​</a></h3><p><code>tenant_id</code>, unique <code>uuid</code>, <code>name</code>, <code>slug</code>, <code>sort_order</code> (default 0), <code>is_active</code> (default true), timestamps, soft deletes. Unique <code>(tenant_id, slug)</code>, index <code>(tenant_id, sort_order)</code>. Tenant-managed lookup; starter slugs <code>general|technical|billing|account|other</code> are lazy-seeded and stay immutable on rename. <strong>Other</strong> cannot be deleted. Spatie activity log name <code>help-desk-categories</code>. Delete is also blocked in the service while tickets exist.</p><h3 id="help-desk-tickets" tabindex="-1"><code>help_desk_tickets</code> <a class="header-anchor" href="#help-desk-tickets" aria-label="Permalink to &quot;`help_desk_tickets`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>number</code> (unique per tenant), <code>subject</code>, nullable <code>description</code>, <code>status</code> (<code>open</code>|<code>in_progress</code>|<code>waiting</code>|<code>resolved</code>|<code>closed</code>), <code>priority</code> (<code>low</code>|<code>medium</code>|<code>high</code>|<code>urgent</code>), nullable <code>category_id</code> (FK → <code>help_desk_categories</code>, null on delete), nullable <code>contact_id</code> (FK → <code>contacts</code>, null on delete; soft entitlement), nullable <code>company_id</code> (FK → <code>companies</code>, null on delete; soft entitlement), <code>assigned_to</code>, <code>created_by</code>, nullable <code>due_at</code> (UTC), soft deletes. Spatie activity log name <code>help-desk</code>. Content edits are <strong>blocked when closed</strong>.</p><h3 id="help-desk-notes-help-desk-activities" tabindex="-1"><code>help_desk_notes</code> / <code>help_desk_activities</code> <a class="header-anchor" href="#help-desk-notes-help-desk-activities" aria-label="Permalink to &quot;`help_desk_notes` / `help_desk_activities`&quot;">​</a></h3><p>Notes (author + body) and ticket timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON; includes <code>status_changed</code>).</p><h2 id="assets-module-tables" tabindex="-1">Assets module tables <a class="header-anchor" href="#assets-module-tables" aria-label="Permalink to &quot;Assets module tables&quot;">​</a></h2><h3 id="assets" tabindex="-1"><code>assets</code> <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;`assets`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>number</code> (unique per tenant; prefix <code>AST-</code> / <code>assets_number_prefix</code>), <code>name</code>, <code>status</code> (<code>active</code>|<code>in_repair</code>|<code>retired</code>|<code>disposed</code>), nullable <code>category</code> (<code>equipment</code>|<code>furniture</code>|<code>vehicle</code>|<code>electronics</code>|<code>software_license</code>|<code>other</code>), nullable <code>manufacturer</code> / <code>model</code> / <code>serial_number</code> / <code>location</code>, nullable <code>purchased_at</code> / <code>warranty_ends_at</code> (dates), nullable <code>purchase_cost</code> / <code>currency</code>, <code>assigned_to</code>, <code>created_by</code>, nullable <code>vendor_id</code> (FK → <code>vendors</code>, null on delete; soft entitlement), nullable <code>employee_id</code> (FK → <code>employees</code>, null on delete; soft entitlement), soft deletes. Spatie activity log name <code>assets</code>.</p><h3 id="asset-notes-asset-activities" tabindex="-1"><code>asset_notes</code> / <code>asset_activities</code> <a class="header-anchor" href="#asset-notes-asset-activities" aria-label="Permalink to &quot;`asset_notes` / `asset_activities`&quot;">​</a></h3><p>Notes (author + body) and asset timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON).</p><h2 id="products-module-tables" tabindex="-1">Products module tables <a class="header-anchor" href="#products-module-tables" aria-label="Permalink to &quot;Products module tables&quot;">​</a></h2><h3 id="product-categories" tabindex="-1"><code>product_categories</code> <a class="header-anchor" href="#product-categories" aria-label="Permalink to &quot;`product_categories`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, nullable <code>description</code>, soft deletes. Tenant-scoped catalog categories; deleting a category nulls linked product <code>category_id</code>.</p><h3 id="products" tabindex="-1"><code>products</code> <a class="header-anchor" href="#products" aria-label="Permalink to &quot;`products`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, unique-per-tenant <code>sku</code>, <code>name</code>, nullable <code>category_id</code>, <code>description</code>, <code>unit</code>, <code>cost</code>, <code>price</code>, nullable 3-character <code>currency</code>, <code>track_stock</code>, nullable <code>reorder_level</code>, <code>status</code> (<code>active</code>|<code>inactive</code>), <code>created_by</code>, soft deletes. Spatie activity log name <code>products</code>.</p><h3 id="product-notes-product-activities" tabindex="-1"><code>product_notes</code> / <code>product_activities</code> <a class="header-anchor" href="#product-notes-product-activities" aria-label="Permalink to &quot;`product_notes` / `product_activities`&quot;">​</a></h3><p>Notes (author + body) and product domain timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON).</p><h2 id="warehouses-module-tables" tabindex="-1">Warehouses module tables <a class="header-anchor" href="#warehouses-module-tables" aria-label="Permalink to &quot;Warehouses module tables&quot;">​</a></h2><h3 id="warehouses" tabindex="-1"><code>warehouses</code> <a class="header-anchor" href="#warehouses" aria-label="Permalink to &quot;`warehouses`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, unique-per-tenant <code>code</code>, <code>name</code>, nullable <code>address</code>, <code>is_default</code>, <code>is_active</code>, <code>created_by</code>, soft deletes. The service protects the sole default warehouse.</p><h3 id="warehouse-notes-warehouse-activities" tabindex="-1"><code>warehouse_notes</code> / <code>warehouse_activities</code> <a class="header-anchor" href="#warehouse-notes-warehouse-activities" aria-label="Permalink to &quot;`warehouse_notes` / `warehouse_activities`&quot;">​</a></h3><p>Notes (author + body) and warehouse domain timeline (<code>type</code>, <code>description</code>, <code>properties</code> JSON).</p><h2 id="inventory-module-tables" tabindex="-1">Inventory module tables <a class="header-anchor" href="#inventory-module-tables" aria-label="Permalink to &quot;Inventory module tables&quot;">​</a></h2><h3 id="stock-levels" tabindex="-1"><code>stock_levels</code> <a class="header-anchor" href="#stock-levels" aria-label="Permalink to &quot;`stock_levels`&quot;">​</a></h3><p><code>tenant_id</code>, <code>product_id</code>, <code>warehouse_id</code>, <code>quantity_on_hand</code>; unique <code>(tenant_id, product_id, warehouse_id)</code>. This is the current per-product, per-warehouse balance.</p><h3 id="stock-movements" tabindex="-1"><code>stock_movements</code> <a class="header-anchor" href="#stock-movements" aria-label="Permalink to &quot;`stock_movements`&quot;">​</a></h3><p><code>tenant_id</code>, <code>product_id</code>, <code>warehouse_id</code>, <code>type</code> (<code>in</code>|<code>out</code>|<code>adjust</code>|<code>transfer_in</code>|<code>transfer_out</code>), <code>quantity</code>, <code>balance_after</code>, nullable polymorphic-style <code>reference_type</code> / <code>reference_id</code>, nullable <code>notes</code>, <code>created_by</code>, <code>created_at</code>. Append-only ledger rows are written by <code>StockService</code>.</p><h3 id="stock-transfers" tabindex="-1"><code>stock_transfers</code> <a class="header-anchor" href="#stock-transfers" aria-label="Permalink to &quot;`stock_transfers`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, unique-per-tenant <code>number</code>, <code>from_warehouse_id</code>, <code>to_warehouse_id</code>, <code>status</code> (<code>draft</code>|<code>in_transit</code>|<code>completed</code>|<code>cancelled</code>), nullable <code>notes</code>, <code>created_by</code>, soft deletes.</p><h3 id="stock-transfer-lines" tabindex="-1"><code>stock_transfer_lines</code> <a class="header-anchor" href="#stock-transfer-lines" aria-label="Permalink to &quot;`stock_transfer_lines`&quot;">​</a></h3><p><code>tenant_id</code>, <code>stock_transfer_id</code> (cascade), <code>product_id</code> (restrict), <code>quantity</code>, timestamps. Unique <code>(stock_transfer_id, product_id)</code>.</p><h2 id="accounting-financial-reports-module-tables" tabindex="-1">Accounting / Financial Reports module tables <a class="header-anchor" href="#accounting-financial-reports-module-tables" aria-label="Permalink to &quot;Accounting / Financial Reports module tables&quot;">​</a></h2><p>Phase 6 Finance. Manual double-entry only; Financial Reports reads posted journal lines (void excluded). Single currency MVP — amounts are decimal, not FX-aware.</p><h3 id="accounts" tabindex="-1"><code>accounts</code> <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;`accounts`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, unique-per-tenant <code>code</code>, <code>name</code>, <code>type</code> (<code>asset</code>|<code>liability</code>|<code>equity</code>|<code>revenue</code>|<code>expense</code>), nullable <code>parent_id</code> (self-FK), <code>is_active</code>, <code>is_system</code>, nullable <code>description</code>, soft deletes. Starter system CoA is lazy-seeded by <code>ChartOfAccountsSeederService</code> on first Accounts list (not via <code>db:seed</code>). System rows cannot change <code>code</code>/<code>type</code> or be deleted.</p><h3 id="journal-entries" tabindex="-1"><code>journal_entries</code> <a class="header-anchor" href="#journal-entries" aria-label="Permalink to &quot;`journal_entries`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, unique-per-tenant <code>number</code> (e.g. <code>JE-00001</code>), <code>entry_date</code>, nullable <code>memo</code>, <code>status</code> (<code>draft</code>|<code>posted</code>|<code>void</code>), nullable <code>posted_at</code> / <code>posted_by</code>, nullable <code>voided_at</code> / <code>voided_by</code> / <code>void_reason</code>, <code>created_by</code>, soft deletes. Post/void run under <code>lockForUpdate()</code> transactions. Only drafts are editable/deletable; void excludes the entry from GL and reports (no reversing journal).</p><h3 id="journal-entry-lines" tabindex="-1"><code>journal_entry_lines</code> <a class="header-anchor" href="#journal-entry-lines" aria-label="Permalink to &quot;`journal_entry_lines`&quot;">​</a></h3><p><code>tenant_id</code>, <code>journal_entry_id</code> (cascade), <code>account_id</code> (restrict), <code>debit</code>, <code>credit</code>, nullable <code>memo</code>, <code>sort_order</code>. Balanced debit/credit enforced in <code>JournalEntryService</code>. Indexes support GL inquiry by account and journal.</p><p>General ledger inquiry (<code>GET /general-ledger</code>) paginates posted lines (default 100, max 500) while returning period opening/closing balances for the full filter set.</p><h2 id="employees-leave-management-attendance-payroll-module-tables" tabindex="-1">Employees / Leave Management / Attendance / Payroll module tables <a class="header-anchor" href="#employees-leave-management-attendance-payroll-module-tables" aria-label="Permalink to &quot;Employees / Leave Management / Attendance / Payroll module tables&quot;">​</a></h2><p>Phase 7 HR. Category <code>hr</code> (sort <code>70</code>). Free Marketplace opt-ins. Leave Management, Attendance, and Payroll hard-depend on Employees; Payroll optionally depends on Accounting for journal post.</p><h3 id="employees" tabindex="-1"><code>employees</code> <a class="header-anchor" href="#employees" aria-label="Permalink to &quot;`employees`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, unique-per-tenant <code>employee_number</code>, <code>first_name</code>, <code>last_name</code>, nullable <code>email</code> / <code>phone</code> / <code>job_title</code> / <code>department</code>, nullable <code>hire_date</code> / <code>termination_date</code>, <code>employment_type</code> (<code>full_time</code>|<code>part_time</code>|<code>contract</code>, default <code>full_time</code>), <code>status</code> (<code>active</code>|<code>inactive</code>|<code>terminated</code>, default <code>active</code>), nullable <code>user_id</code> (FK users), nullable <code>active_user_id</code> (mirrors <code>user_id</code> while active; cleared on soft delete; unique <code>(tenant_id, active_user_id)</code>), nullable <code>notes</code>, <code>created_by</code>, soft deletes. Indexes on <code>(tenant_id, status)</code> and <code>(tenant_id, last_name)</code>.</p><h3 id="leave-types" tabindex="-1"><code>leave_types</code> <a class="header-anchor" href="#leave-types" aria-label="Permalink to &quot;`leave_types`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>name</code>, unique-per-tenant <code>code</code>, <code>is_paid</code>, <code>annual_allowance</code> (decimal 8,2), nullable <code>description</code>, <code>is_active</code>, <code>created_by</code>, soft deletes.</p><h3 id="leave-balances" tabindex="-1"><code>leave_balances</code> <a class="header-anchor" href="#leave-balances" aria-label="Permalink to &quot;`leave_balances`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>employee_id</code> (cascade), <code>leave_type_id</code> (cascade), <code>year</code>, <code>entitled</code> / <code>used</code> / <code>remaining</code> (decimal 8,2), <code>created_by</code>, soft deletes. Unique <code>(tenant_id, employee_id, leave_type_id, year)</code>.</p><h3 id="leave-requests" tabindex="-1"><code>leave_requests</code> <a class="header-anchor" href="#leave-requests" aria-label="Permalink to &quot;`leave_requests`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>employee_id</code>, <code>leave_type_id</code>, <code>start_date</code>, <code>end_date</code>, <code>days</code>, <code>status</code> (<code>draft</code>|<code>pending</code>|<code>approved</code>|<code>rejected</code>|<code>cancelled</code>), nullable <code>reason</code>, nullable <code>reviewed_by</code> / <code>reviewed_at</code> / <code>review_notes</code>, <code>created_by</code>, soft deletes. Approve applies days to the matching leave balance.</p><h3 id="attendance-records" tabindex="-1"><code>attendance_records</code> <a class="header-anchor" href="#attendance-records" aria-label="Permalink to &quot;`attendance_records`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>employee_id</code>, <code>date</code>, nullable <code>check_in</code> / <code>check_out</code> (time), <code>status</code> (<code>present</code>|<code>absent</code>|<code>half_day</code>|<code>remote</code>, default <code>present</code>), nullable <code>notes</code>, <code>created_by</code>, soft deletes. Unique <code>(tenant_id, employee_id, date)</code>.</p><h3 id="payroll-profiles" tabindex="-1"><code>payroll_profiles</code> <a class="header-anchor" href="#payroll-profiles" aria-label="Permalink to &quot;`payroll_profiles`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>employee_id</code> (unique per tenant), <code>base_salary</code> (decimal 15,2), <code>currency</code> (char 3, default <code>USD</code>), <code>pay_frequency</code> (<code>monthly</code>|<code>biweekly</code>|<code>weekly</code>), nullable <code>effective_from</code> / <code>notes</code>, <code>created_by</code>, soft deletes.</p><h3 id="pay-runs" tabindex="-1"><code>pay_runs</code> <a class="header-anchor" href="#pay-runs" aria-label="Permalink to &quot;`pay_runs`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>period_start</code>, <code>period_end</code>, <code>status</code> (<code>draft</code>|<code>approved</code>|<code>paid</code>), nullable <code>notes</code>, nullable <code>approved_by</code> / <code>approved_at</code> / <code>paid_at</code>, nullable <code>journal_entry_id</code> (Accounting soft post), <code>created_by</code>, soft deletes.</p><h3 id="pay-run-lines" tabindex="-1"><code>pay_run_lines</code> <a class="header-anchor" href="#pay-run-lines" aria-label="Permalink to &quot;`pay_run_lines`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code>, <code>pay_run_id</code> (cascade), <code>employee_id</code>, <code>gross</code> / <code>adjustments</code> / <code>net</code> (decimal 15,2), nullable <code>notes</code>, timestamps (no soft deletes). Unique <code>(pay_run_id, employee_id)</code>. Net = gross + adjustments.</p><h2 id="communication-templates-module-tables" tabindex="-1">Communication Templates module tables <a class="header-anchor" href="#communication-templates-module-tables" aria-label="Permalink to &quot;Communication Templates module tables&quot;">​</a></h2><h3 id="communication-templates" tabindex="-1"><code>communication_templates</code> <a class="header-anchor" href="#communication-templates" aria-label="Permalink to &quot;`communication_templates`&quot;">​</a></h3><p><code>tenant_id</code>, <code>uuid</code> (route key), <code>name</code>, <code>context</code> (e.g. <code>leads</code>), <code>channel</code> (MVP: <code>whatsapp</code>), <code>category</code> (nullable), <code>body</code> (plain text), <code>is_active</code>, <code>created_by</code>, <code>updated_by</code>, <code>last_used_at</code>, soft deletes. Unique name per tenant+context+channel among non-deleted rows. Placeholders are not stored as rows — they come from the in-code registry.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><h3 id="notifications-1" tabindex="-1"><code>notifications</code> <a class="header-anchor" href="#notifications-1" aria-label="Permalink to &quot;`notifications`&quot;">​</a></h3><p>Laravel standard table: UUID <code>id</code> (stable public notification id), <code>type</code>, morphs <code>notifiable</code>, <code>data</code> (JSON envelope <code>schema_version: 1</code>), <code>read_at</code>, timestamps.</p><p>Indexes: morph index plus composites <code>(notifiable_type, notifiable_id, read_at)</code> and <code>(notifiable_type, notifiable_id, created_at)</code> for unread/list queries.</p><p>Retention: <code>php artisan notifications:prune --days=90</code> (scheduled weekly) deletes <strong>read</strong> rows only. See <a href="/developer-guide/notification-architecture-contract">notification-architecture-contract</a>.</p><h2 id="table-dictionary-licensing-catalog" tabindex="-1">Table dictionary (licensing &amp; catalog) <a class="header-anchor" href="#table-dictionary-licensing-catalog" aria-label="Permalink to &quot;Table dictionary (licensing &amp; catalog)&quot;">​</a></h2><h3 id="module-categories" tabindex="-1"><code>module_categories</code> <a class="header-anchor" href="#module-categories" aria-label="Permalink to &quot;`module_categories`&quot;">​</a></h3><p><code>name</code>, <code>slug</code> (unique), <code>description</code>, <code>sort_order</code>, <code>is_active</code>.</p><h3 id="modules" tabindex="-1"><code>modules</code> <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;`modules`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>uuid</code></td><td>Unique public id</td></tr><tr><td><code>name</code>, <code>slug</code> (unique), <code>description</code>, <code>icon</code></td><td></td></tr><tr><td><code>category_id</code></td><td>FK <code>module_categories</code>, nullable</td></tr><tr><td><code>monthly_price</code>, <code>yearly_price</code>, <code>currency</code>, <code>setup_fee</code></td><td>Catalog amounts; default CRM modules are <code>0</code>. No provider IDs on modules</td></tr><tr><td><code>trial_days</code>, <code>version</code>, <code>status</code></td><td><code>draft</code> | <code>published</code> | <code>deprecated</code></td></tr><tr><td><code>availability</code></td><td>Marketing phase: <code>available</code> | <code>in_progress</code> | <code>planned</code> (website public catalog; independent of commercial <code>status</code>)</td></tr><tr><td><code>is_default_included</code></td><td>Auto-install on workspace create</td></tr><tr><td><code>is_billable</code></td><td>Whether the module can be charged when platform-managed</td></tr><tr><td><code>sort_order</code>, <code>is_active</code></td><td></td></tr><tr><td>soft deletes</td><td></td></tr></tbody></table><p>Default-included catalog modules today: <strong>Leads</strong>, <strong>Tasks</strong>, <strong>ToDos</strong> (<code>is_default_included=true</code>, <code>is_billable=false</code>). Free Marketplace opt-in modules (including Opportunities under category <code>sales</code>) use <code>is_default_included=false</code>, <code>is_billable=false</code>. Production receives new catalog modules via <strong>data migrations</strong> (<code>DefaultModuleRegistrar</code>), not seeders. Modules are pure licensing products — they do not store permission lists. User authorization uses Spatie Roles &amp; Permissions separately.</p><h3 id="payment-gateway-module-prices" tabindex="-1"><code>payment_gateway_module_prices</code> <a class="header-anchor" href="#payment-gateway-module-prices" aria-label="Permalink to &quot;`payment_gateway_module_prices`&quot;">​</a></h3><p>Per-gateway catalog mapping (provider-agnostic price references):</p><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>payment_gateway_id</code>, <code>module_id</code>, <code>billing_cycle</code></td><td>Unique triple (<code>monthly</code> | <code>yearly</code>)</td></tr><tr><td><code>gateway_product_reference</code></td><td>e.g. Stripe <code>prod_…</code>, PayPal plan id — nullable</td></tr><tr><td><code>gateway_price_reference</code></td><td>e.g. Stripe <code>price_…</code> — required for checkout when gateway <code>requiresProductMapping()</code></td></tr><tr><td><code>gateway_metadata</code></td><td>JSON bag for driver-specific extras</td></tr></tbody></table><h3 id="module-dependencies" tabindex="-1"><code>module_dependencies</code> <a class="header-anchor" href="#module-dependencies" aria-label="Permalink to &quot;`module_dependencies`&quot;">​</a></h3><p><code>(module_id, depends_on_module_id)</code> unique. Optional flag <code>is_optional</code>. Enforced on marketplace install.</p><h3 id="workspace-module-subscriptions" tabindex="-1"><code>workspace_module_subscriptions</code> <a class="header-anchor" href="#workspace-module-subscriptions" aria-label="Permalink to &quot;`workspace_module_subscriptions`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>tenant_id</code>, <code>module_id</code></td><td>Unique pair</td></tr><tr><td><code>status</code></td><td><code>pending</code> | <code>trial</code> | <code>active</code> | <code>expired</code> | <code>cancelled</code> | <code>suspended</code></td></tr><tr><td><code>source</code></td><td><code>included</code> | <code>purchased</code> | <code>trial</code></td></tr><tr><td><code>billing_cycle</code>, <code>price</code>, <code>currency</code>, <code>is_billable</code></td><td>Snapshot for billing</td></tr><tr><td>period timestamps</td><td><code>trial_*</code>, <code>starts_at</code>, <code>ends_at</code>, <code>renews_at</code>, <code>cancelled_at</code></td></tr><tr><td><code>provider</code>, <code>provider_subscription_id</code></td><td>Gateway-facing refs</td></tr><tr><td><code>payment_gateway_id</code></td><td>FK to <code>payment_gateways</code> (nullable) — which driver owns renewals</td></tr><tr><td>soft deletes</td><td></td></tr></tbody></table><h3 id="workspace-module-subscription-history" tabindex="-1"><code>workspace_module_subscription_history</code> <a class="header-anchor" href="#workspace-module-subscription-history" aria-label="Permalink to &quot;`workspace_module_subscription_history`&quot;">​</a></h3><p>Append-only events: <code>module_installed</code>, <code>module_purchase_pending</code>, <code>module_activated</code>, <code>module_cancelled</code>, <code>module_suspended</code>, etc.</p><h3 id="tenants-billing-profile-columns" tabindex="-1"><code>tenants</code> billing profile columns <a class="header-anchor" href="#tenants-billing-profile-columns" aria-label="Permalink to &quot;`tenants` billing profile columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>billing_anchor_day</code></td><td>1–28</td></tr><tr><td><code>billing_cycle</code></td><td>Workspace default (<code>monthly</code> / <code>yearly</code>)</td></tr><tr><td><code>proration_mode</code></td><td><code>prorated</code> | <code>free_until_next</code> | <code>none</code></td></tr><tr><td><code>next_billing_at</code></td><td>Next consolidated invoice run</td></tr></tbody></table><p>Workspace profile columns include <code>company_name</code>, <code>workspace_name</code>, <code>slug</code>, <code>email</code>, <code>phone</code>, <code>logo_path</code>, <code>notes</code>, <code>timezone</code>, <code>currency</code>, <code>country</code>, <code>locale</code>. There is <strong>no</strong> <code>owner_id</code> or <code>address</code> column.</p><h2 id="table-dictionary-financial-ledger" tabindex="-1">Table dictionary (financial ledger) <a class="header-anchor" href="#table-dictionary-financial-ledger" aria-label="Permalink to &quot;Table dictionary (financial ledger)&quot;">​</a></h2><h3 id="payment-gateways" tabindex="-1"><code>payment_gateways</code> <a class="header-anchor" href="#payment-gateways" aria-label="Permalink to &quot;`payment_gateways`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>code</code> (unique), <code>name</code>, <code>driver</code></td><td>Driver class FQCN</td></tr><tr><td><code>is_active</code>, <code>is_default</code>, <code>mode</code></td><td><code>sandbox</code> | <code>live</code></td></tr><tr><td><code>config</code></td><td>Encrypted array (credentials); never expose secrets via API</td></tr><tr><td><code>supported_currencies</code>, <code>capabilities</code></td><td>Cached/display; drivers remain source of truth</td></tr><tr><td><code>webhook_status</code>, <code>webhook_last_received_at</code></td><td>Ingress health</td></tr><tr><td><code>last_tested_at</code>, <code>last_test_status</code>, <code>last_test_message</code></td><td>Connection probe</td></tr><tr><td><code>sort_order</code></td><td></td></tr></tbody></table><p>Seeded: <code>manual</code>, <code>stripe</code>.</p><h3 id="payment-methods" tabindex="-1"><code>payment_methods</code> <a class="header-anchor" href="#payment-methods" aria-label="Permalink to &quot;`payment_methods`&quot;">​</a></h3><p>Workspace preferred / saved methods: <code>tenant_id</code>, <code>payment_gateway_id</code>, <code>type</code>, <code>brand</code>, <code>last_four</code>, encrypted <code>token</code>, <code>is_default</code>.</p><h3 id="payment-attempts" tabindex="-1"><code>payment_attempts</code> <a class="header-anchor" href="#payment-attempts" aria-label="Permalink to &quot;`payment_attempts`&quot;">​</a></h3><p>Gateway-agnostic checkout/charge attempts linked to optional <code>payment_id</code> / <code>invoice_id</code>.</p><h3 id="gateway-logs-webhook-logs" tabindex="-1"><code>gateway_logs</code> / <code>webhook_logs</code> <a class="header-anchor" href="#gateway-logs-webhook-logs" aria-label="Permalink to &quot;`gateway_logs` / `webhook_logs`&quot;">​</a></h3><p>Operational admin/driver events and inbound webhook audit trail.</p><h3 id="billing-addresses" tabindex="-1"><code>billing_addresses</code> <a class="header-anchor" href="#billing-addresses" aria-label="Permalink to &quot;`billing_addresses`&quot;">​</a></h3><p>Workspace billing addresses: <code>tenant_id</code>, address lines, <code>is_default</code>.</p><h3 id="taxes-coupons-refunds-credit-notes" tabindex="-1"><code>taxes</code>, <code>coupons</code>, <code>refunds</code>, <code>credit_notes</code> <a class="header-anchor" href="#taxes-coupons-refunds-credit-notes" aria-label="Permalink to &quot;`taxes`, `coupons`, `refunds`, `credit_notes`&quot;">​</a></h3><p>Supporting ledger tables for future tax/discount/refund flows. Not exposed in Central v1 read APIs yet.</p><h3 id="invoices" tabindex="-1"><code>invoices</code> <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;`invoices`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>uuid</code>, <code>number</code></td><td>Unique identifiers</td></tr><tr><td><code>tenant_id</code></td><td>FK <code>tenants</code></td></tr><tr><td><code>status</code></td><td><code>draft</code> | <code>open</code> | <code>paid</code> | <code>void</code> | …</td></tr><tr><td><code>subtotal</code>, <code>tax_total</code>, <code>discount_total</code>, <code>total</code>, <code>amount_paid</code>, <code>amount_due</code></td><td></td></tr><tr><td><code>payment_gateway_id</code>, <code>coupon_id</code>, <code>billing_address_id</code></td><td>Nullable FKs</td></tr><tr><td><code>issue_date</code>, <code>due_date</code>, <code>paid_at</code></td><td></td></tr><tr><td>soft deletes</td><td></td></tr></tbody></table><h3 id="invoice-items" tabindex="-1"><code>invoice_items</code> <a class="header-anchor" href="#invoice-items" aria-label="Permalink to &quot;`invoice_items`&quot;">​</a></h3><p>Line items: <code>invoice_id</code>, <code>type</code> (<code>module</code> | <code>proration</code> | …), optional <code>module_id</code> + <code>workspace_module_subscription_id</code>, <code>description</code>, <code>quantity</code>, <code>unit_amount</code>, <code>total</code>, <code>meta</code>.</p><h3 id="payments" tabindex="-1"><code>payments</code> <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;`payments`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>uuid</code></td><td>Unique public id</td></tr><tr><td><code>tenant_id</code>, <code>invoice_id</code></td><td></td></tr><tr><td><code>payment_gateway_id</code>, <code>payment_method_id</code></td><td></td></tr><tr><td><code>amount</code>, <code>tax</code>, <code>currency</code>, <code>status</code></td><td><code>pending</code> | <code>succeeded</code> | <code>failed</code> | …</td></tr><tr><td><code>transaction_id</code>, <code>reference</code>, <code>gateway_response</code>, <code>webhook_payload</code></td><td></td></tr><tr><td><code>captured_at</code>, <code>failure_reason</code></td><td></td></tr></tbody></table><h3 id="payment-transactions" tabindex="-1"><code>payment_transactions</code> <a class="header-anchor" href="#payment-transactions" aria-label="Permalink to &quot;`payment_transactions`&quot;">​</a></h3><p>Append-only gateway status events per payment: <code>payment_id</code>, <code>status</code>, <code>amount</code>, <code>error</code>, <code>raw_payload</code>.</p><h2 id="table-dictionary-impersonation" tabindex="-1">Table dictionary (impersonation) <a class="header-anchor" href="#table-dictionary-impersonation" aria-label="Permalink to &quot;Table dictionary (impersonation)&quot;">​</a></h2><h3 id="impersonation-sessions" tabindex="-1"><code>impersonation_sessions</code> <a class="header-anchor" href="#impersonation-sessions" aria-label="Permalink to &quot;`impersonation_sessions`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>central_user_id</code></td><td>FK <code>central_users</code> (admin)</td></tr><tr><td><code>tenant_id</code></td><td>FK <code>tenants</code></td></tr><tr><td><code>reason</code></td><td>Required audit text</td></tr><tr><td><code>ip_address</code>, <code>user_agent</code></td><td>Request metadata</td></tr><tr><td><code>started_at</code>, <code>ended_at</code>, <code>duration_seconds</code></td><td>Session window</td></tr></tbody></table><h3 id="user-impersonation-sessions" tabindex="-1"><code>user_impersonation_sessions</code> <a class="header-anchor" href="#user-impersonation-sessions" aria-label="Permalink to &quot;`user_impersonation_sessions`&quot;">​</a></h3><p>Same-workspace tenant user → user sessions (Users/auth core; not Central).</p><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><code>tenant_id</code></td><td>FK <code>tenants</code></td></tr><tr><td><code>actor_user_id</code></td><td>FK <code>users</code> (impersonating admin)</td></tr><tr><td><code>target_user_id</code></td><td>FK <code>users</code> (impersonated member)</td></tr><tr><td><code>personal_access_token_id</code></td><td>Sanctum PAT minted for the target; revoked on end</td></tr><tr><td><code>reason</code></td><td>Required audit text (5–1000 chars at API)</td></tr><tr><td><code>ip_address</code>, <code>user_agent</code></td><td>Request metadata</td></tr><tr><td><code>started_at</code>, <code>expires_at</code>, <code>ended_at</code>, <code>duration_seconds</code></td><td>Session window (TTL 1 hour)</td></tr></tbody></table><h3 id="system-settings" tabindex="-1"><code>system_settings</code> <a class="header-anchor" href="#system-settings" aria-label="Permalink to &quot;`system_settings`&quot;">​</a></h3><p>Key/value store for Central Application settings (<code>key</code> unique, <code>value</code>, <code>type</code>, <code>group</code>).</p><p>Groups: <code>general</code>, <code>localization</code>, <code>mail</code>, <code>branding</code>, <code>security</code>, <code>maintenance</code>, <code>billing</code>.</p><p>Sensitive values (<code>mail_password</code>) are encrypted at rest and masked in the admin API. Logo/favicon paths store relative object keys (<code>branding/logos</code>, <code>branding/favicons</code>) on the configured uploads disk (<code>public</code> locally / <code>s3</code> in production).</p><p><code>maintenance_mode</code> gates the <strong>Tenant Application</strong> only — never Laravel <code>artisan down</code> for Central.</p><p>Catalog (see <code>App\\Support\\SystemSettingDefinitions</code>):</p><table tabindex="0"><thead><tr><th>Group</th><th>Keys</th></tr></thead><tbody><tr><td>general</td><td><code>app_name</code>, <code>company_name</code>, <code>timezone</code>, <code>locale</code>, <code>currency</code>, <code>registration_enabled</code></td></tr><tr><td>localization</td><td><code>date_format</code>, <code>time_format</code></td></tr><tr><td>mail</td><td><code>mail_driver</code>, <code>mail_host</code>, <code>mail_port</code>, <code>mail_username</code>, <code>mail_password</code>, <code>mail_encryption</code>, <code>mail_from_name</code>, <code>mail_from_address</code></td></tr><tr><td>branding</td><td><code>button_color</code>, <code>support_email</code>, <code>logo_path</code>, <code>favicon_path</code></td></tr><tr><td>security</td><td><code>session_lifetime_minutes</code>, <code>password_min_length</code>, <code>password_require_special</code></td></tr><tr><td>maintenance</td><td><code>maintenance_mode</code>, <code>maintenance_message</code>, <code>maintenance_eta</code></td></tr><tr><td>billing</td><td><code>invoice_prefix</code>, <code>proration_mode</code>, <code>trial_enabled</code>, <code>stripe_enabled</code>, <code>stripe_webhook_configured</code>, <code>default_payment_gateway</code></td></tr></tbody></table><p>Obsolete (removed by migration/seeder): <code>primary_color</code>, <code>queue_connection_display</code>, <code>filesystem_disk</code>, <code>feature_registration</code>, <code>feature_invites</code>, <code>default_plan_id</code>.</p><p>Docs: <a href="/user-guide/central-settings-overview">settings/settings.md</a>.</p><h3 id="tenant-settings" tabindex="-1"><code>tenant_settings</code> <a class="header-anchor" href="#tenant-settings" aria-label="Permalink to &quot;`tenant_settings`&quot;">​</a></h3><p>Per-workspace overrides of Central defaults (<code>tenant_id</code> + <code>key</code> unique, <code>value</code>, <code>type</code>, <code>group</code>).</p><p>Resolution hierarchy (via <code>TenantSettingService</code>): tenant override → tenant profile columns → Central <code>system_settings</code> → system default.</p><p>Groups: <code>general</code>, <code>security</code>, <code>branding</code>, <code>mail</code>, <code>notifications</code>, <code>attendance</code>, <code>leads</code>, <code>team-chat</code>. Sensitive <code>mail_password</code> encrypted. Branding files under <code>tenants/{uuid}/branding/…</code> on the configured uploads disk. <code>session_lifetime_minutes</code> (<code>0</code> = never expire) may override Central. Team Chat retention key: <code>team-chat.retention_days</code> (<code>0</code> = forever; else days until scheduled <code>team-chat:purge-expired</code> deletes messages and attachment files — always schedule the command; it no-ops at <code>0</code>). Workspace trash retention key: <code>trash.retention_days</code> (<code>0</code> = forever; else days until scheduled <code>trash:purge-expired</code> force-deletes SoftDeletes rows via <code>TrashPurgeRegistry</code>, excluding EmailAccount — always schedule with <code>withoutOverlapping(120)</code>; no-ops at <code>0</code>).</p><p>Docs: <a href="/user-guide/tenant-settings-overview">settings/tenant-settings.md</a>.</p><h2 id="removed-tables" tabindex="-1">Removed tables <a class="header-anchor" href="#removed-tables" aria-label="Permalink to &quot;Removed tables&quot;">​</a></h2><p><code>plans</code>, <code>plan_module</code>, <code>plan_feature</code>, <code>plan_limits</code>, <code>limit_definitions</code>, <code>tenant_usage_counters</code>, <code>tenant_subscriptions</code>, <code>subscription_events</code> (replaced by module subscription history), <code>features</code> (removed — modules are licensing only; Spatie permissions handle authorization).</p><h2 id="archive-vs-soft-delete" tabindex="-1">Archive vs soft delete <a class="header-anchor" href="#archive-vs-soft-delete" aria-label="Permalink to &quot;Archive vs soft delete&quot;">​</a></h2><p>Unchanged: <code>archived_at</code> is independent of soft delete.</p>',279)])])}const m=o(c,[["render",s]]);export{_ as __pageData,m as default};
